from html.parser import HTMLParser
import sys,re
class P(HTMLParser):
 def __init__(self): super().__init__(); self.depth=0; self.buf=[]; self.out=[]; self.skip=0
 def handle_starttag(self,t,a):
  if t in ('script','style'): self.skip+=1
  if t in ('h1','h2','h3','h4','h5','p','li','td','th','a'): self.depth+=1; self.buf=[]
 def handle_data(self,d):
  if not self.skip and self.depth: self.buf.append(' '.join(d.split()))
 def handle_endtag(self,t):
  if t in ('script','style'): self.skip=max(0,self.skip-1)
  if t in ('h1','h2','h3','h4','h5','p','li','td','th','a') and self.depth:
   s=' '.join(' '.join(self.buf).split())
   if s and len(s)>1: self.out.append(s)
   self.depth-=1; self.buf=[]
text=open(sys.argv[1],encoding='utf-8',errors='ignore').read(); p=P(); p.feed(text)
seen=set()
for s in p.out:
 if s not in seen and not re.fullmatch(r'[-अअ+×#⮞]+',s): print(s); seen.add(s)
PY
 done"

